+  if (info.length === 0) return;
+  const { columns, values } = info[0];
+  const colunas: Record<string, number> = {};
+  columns.forEach((c, i) => { colunas[c] = i; });
+  const linha = values.find((v) => v[colunas.name] === "lido_em");
